import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    q = int(next(it))
    out_lines = []
    for _ in range(q):
        m = int(next(it))
        a = [int(next(it)) for _ in range(m)]
        L = [0] * m
        R = [0] * m

        # 从左到右扫描，维护前缀最大值及其最右位置
        mx = -1
        pos = -1
        for i in range(m):
            L[i] = pos
            if a[i] > mx:
                mx = a[i]
                pos = i
            elif a[i] == mx:
                pos = i

        # 从右到左扫描，维护后缀最大值及其最左位置
        mx = -1
        pos = -1
        for i in range(m - 1, -1, -1):
            R[i] = pos
            if a[i] > mx:
                mx = a[i]
                pos = i
            elif a[i] == mx:
                pos = i

        ans = 0
        for p in range(1, m - 1):
            if p - L[p] == R[p] - p:
                ans += 1
        out_lines.append(str(ans))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
```

